package com.ferreteriahuaman.repository;
import com.ferreteriahuaman.dto.PurchaseModels.*;
import com.ferreteriahuaman.dto.CatalogModels.Page;
import java.sql.*;import java.time.*;import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
@Repository @Profile("db")
public class PurchaseRepository {
 public enum Kind {
  ORDER("orden_compra","id_orden_compra","detalle_orden_compra","id_detalle_oc","estado_orden","total_estimado","cantidad_pedida","COM.OC"),
  RECEIPT("ingreso_mercaderia","id_ingreso","detalle_ingreso","id_detalle_ingreso","estado_ingreso","total","cantidad_recibida","COM.INGRESO");
  public final String table,id,lines,lineId,status,total,quantity,permission;
  Kind(String t,String i,String l,String li,String s,String tot,String q,String p){table=t;id=i;lines=l;lineId=li;status=s;total=tot;quantity=q;permission=p;}
 }
 private final JdbcTemplate jdbc;public PurchaseRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private String decimal(ResultSet r,String field)throws SQLException{var v=r.getBigDecimal(field);return v==null?null:v.toPlainString();}
 private String pattern(String value){String e=Character.toString(92);return "%"+value.replace(e,e+e).replace("%",e+"%").replace("_",e+"_")+"%";}
 private static final String SUPPLIER="select *,coalesce(fecmod,feccre) version from huaman.proveedor";
 private Supplier supplier(ResultSet r,int n)throws SQLException{return new Supplier(r.getLong("id_proveedor"),r.getString("ruc"),r.getString("razon_social"),r.getString("contacto"),r.getString("telefono"),r.getString("correo"),r.getString("direccion"),r.getString("estado"),r.getObject("version",LocalDateTime.class));}
 public Page<Supplier> suppliers(String q,String state,int page,int size){String filter=" where (ruc ilike ? or razon_social ilike ?) and (?='' or estado=?)",p=pattern(q);long total=jdbc.queryForObject("select count(*) from huaman.proveedor"+filter,Long.class,p,p,state,state);return new Page<>(jdbc.query(SUPPLIER+filter+" order by lower(razon_social),id_proveedor limit ? offset ?",this::supplier,p,p,state,state,size,(long)page*size),total,page,size);}
 public Optional<Supplier> supplier(long id,boolean lock){return jdbc.query(SUPPLIER+" where id_proveedor=?"+(lock?" for update":""),this::supplier,id).stream().findFirst();}
 public long createSupplier(SupplierInput i){return jdbc.queryForObject("insert into huaman.proveedor(ruc,razon_social,contacto,telefono,correo,direccion) values(?,?,?,?,?,?) returning id_proveedor",Long.class,i.ruc(),i.razonSocial().strip(),i.contacto(),i.telefono(),i.correo(),i.direccion());}
 public void updateSupplier(long id,SupplierInput i){jdbc.update("update huaman.proveedor set ruc=?,razon_social=?,contacto=?,telefono=?,correo=?,direccion=? where id_proveedor=?",i.ruc(),i.razonSocial().strip(),i.contacto(),i.telefono(),i.correo(),i.direccion(),id);}
 public void supplierState(long id,String state){jdbc.update("update huaman.proveedor set estado=? where id_proveedor=?",state,id);}
 public boolean pendingSupplier(long id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from huaman.orden_compra where id_proveedor=? and estado='A' and estado_orden in ('BORRADOR','EMITIDA','PARCIAL')) or exists(select 1 from huaman.ingreso_mercaderia where id_proveedor=? and estado='A' and estado_ingreso='BORRADOR')",Boolean.class,id,id));}
 public boolean supplierHistory(long id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from huaman.orden_compra where id_proveedor=?) or exists(select 1 from huaman.ingreso_mercaderia where id_proveedor=?)",Boolean.class,id,id));}
 private String select(Kind k){return "select d.*,s.razon_social proveedor,coalesce(d.fecmod,d.feccre) version from huaman."+k.table+" d join huaman.proveedor s on s.id_proveedor=d.id_proveedor";}
 private Document document(ResultSet r,Kind k)throws SQLException{return new Document(r.getLong(k.id),r.getLong("numero"),r.getLong("id_proveedor"),r.getString("proveedor"),r.getObject(k==Kind.ORDER?"fecha":"fecha_ingreso",LocalDate.class),k==Kind.ORDER?r.getObject("fecha_entrega_estimada",LocalDate.class):null,k==Kind.RECEIPT?r.getObject("id_orden_compra",Long.class):null,k==Kind.RECEIPT?r.getString("nro_guia"):null,r.getString("observacion"),decimal(r,k.total),r.getString(k.status),r.getObject("version",LocalDateTime.class));}
 public Page<Document> list(Kind k,String q,String state,Long supplier,int page,int size){String p=pattern(q),f=" where (s.razon_social ilike ? or d.numero::text ilike ?) and (?='' or d."+k.status+"=?) and (?::bigint is null or d.id_proveedor=?)";Object[] args={p,p,state,state,supplier,supplier};long total=jdbc.queryForObject("select count(*) from huaman."+k.table+" d join huaman.proveedor s on s.id_proveedor=d.id_proveedor"+f,Long.class,args);var params=new ArrayList<Object>(Arrays.asList(args));params.add(size);params.add((long)page*size);return new Page<>(jdbc.query(select(k)+f+" order by d."+k.id+" desc limit ? offset ?",(r,n)->document(r,k),params.toArray()),total,page,size);}
 public Optional<Document> get(Kind k,long id,boolean lock){return jdbc.query(select(k)+" where d."+k.id+"=?"+(lock?" for update of d":""),(r,n)->document(r,k),id).stream().findFirst();}
 public long create(Kind k,DocumentInput i){if(k==Kind.ORDER)return jdbc.queryForObject("insert into huaman.orden_compra(id_proveedor,fecha,fecha_entrega_estimada,observacion) values(?,?,?,?) returning id_orden_compra",Long.class,i.proveedorId(),i.fecha(),i.entregaEstimada(),i.observacion());return jdbc.queryForObject("insert into huaman.ingreso_mercaderia(id_proveedor,fecha_ingreso,id_orden_compra,nro_guia,observacion) values(?,?,?,?,?) returning id_ingreso",Long.class,i.proveedorId(),i.fecha(),i.ordenId(),i.guia(),i.observacion());}
 public void update(Kind k,long id,DocumentInput i){if(k==Kind.ORDER)jdbc.update("update huaman.orden_compra set fecha=?,fecha_entrega_estimada=?,observacion=? where id_orden_compra=?",i.fecha(),i.entregaEstimada(),i.observacion(),id);else jdbc.update("update huaman.ingreso_mercaderia set fecha_ingreso=?,nro_guia=?,observacion=? where id_ingreso=?",i.fecha(),i.guia(),i.observacion(),id);}
 private Line line(ResultSet r,Kind k)throws SQLException{return new Line(r.getLong(k.lineId),r.getLong("id_producto"),r.getString("producto"),r.getLong("id_presentacion"),r.getString("presentacion_nombre"),r.getString("unidad_base_simbolo"),decimal(r,"factor_base"),decimal(r,k.quantity),decimal(r,"cantidad_base"),k==Kind.ORDER?decimal(r,"cantidad_recibida_base"):null,k==Kind.ORDER?decimal(r,"cantidad_cancelada_base"):null,decimal(r,"costo_unitario"),decimal(r,"importe_adquisicion"),k==Kind.RECEIPT?r.getObject("id_detalle_oc",Long.class):null,k==Kind.RECEIPT?r.getString("condicion_fisica"):null,k==Kind.RECEIPT?r.getObject("piezas",Integer.class):null,r.getString("estado"));}
 public List<Line> lines(Kind k,long id){return jdbc.query("select l.*,p.nombre producto from huaman."+k.lines+" l join huaman.producto p on p.id_producto=l.id_producto where l."+k.id+"=? order by l."+k.lineId,(r,n)->line(r,k),id);}
 public long addLine(Kind k,long id,LineInput i){if(k==Kind.ORDER)return jdbc.queryForObject("insert into huaman.detalle_orden_compra(id_orden_compra,id_producto,id_presentacion,cantidad_pedida,costo_unitario) values(?,?,?,?,?) returning id_detalle_oc",Long.class,id,i.productoId(),i.presentacionId(),i.cantidad(),i.costoUnitario());return jdbc.queryForObject("insert into huaman.detalle_ingreso(id_ingreso,id_producto,id_presentacion,cantidad_recibida,costo_unitario,id_detalle_oc,condicion_fisica,piezas) values(?,?,?,?,?,?,?,?) returning id_detalle_ingreso",Long.class,id,i.productoId(),i.presentacionId(),i.cantidad(),i.costoUnitario(),i.detalleOrdenId(),i.condicion(),i.piezas());}
 public void updateLine(Kind k,long id,LineInput i){if(k==Kind.ORDER)jdbc.update("update huaman.detalle_orden_compra set cantidad_pedida=?,costo_unitario=? where id_detalle_oc=?",i.cantidad(),i.costoUnitario(),id);else jdbc.update("update huaman.detalle_ingreso set cantidad_recibida=?,costo_unitario=?,condicion_fisica=?,piezas=? where id_detalle_ingreso=?",i.cantidad(),i.costoUnitario(),i.condicion(),i.piezas(),id);}
 public void lineState(Kind k,long id,String state){jdbc.update("update huaman."+k.lines+" set estado=? where "+k.lineId+"=?",state,id);}
 public boolean retry(Kind k,long id,UUID key){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from huaman."+k.table+" where "+k.id+"=? and "+(k==Kind.ORDER?"clave_emision":"clave_confirmacion")+"=?)",Boolean.class,id,key));}
 public long process(Kind k,long id,UUID key,boolean cancel,String reason){String function=cancel?(k==Kind.ORDER?"anular_orden_compra":"anular_ingreso_borrador"):(k==Kind.ORDER?"emitir_orden_compra":"confirmar_ingreso");return cancel?jdbc.queryForObject("select huaman."+function+"(?,?,?)",Long.class,id,key,reason):jdbc.queryForObject("select huaman."+function+"(?,?)",Long.class,id,key);}
 public boolean cancelRetry(Kind k,long id,UUID key){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from huaman."+k.table+" where "+k.id+"=? and clave_anulacion=?)",Boolean.class,id,key));}
 public void event(long actor,String action,String entity,long id,String before,String after,UUID key){jdbc.update("insert into huaman.bitacora_evento(id_usuario,accion,entidad,id_entidad,valor_anterior,valor_nuevo,referencia) values(?,?,?,?,?::jsonb,?::jsonb,?)",actor,action,entity,id,before,after,key==null?null:key.toString());}
 public Optional<Long> creationRetry(long actor,String action,UUID key,String input){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"CREAR_COMPRA:"+key);var matches=jdbc.queryForList("select id_entidad, id_usuario=? and accion=? and valor_nuevo->'solicitud'=?::jsonb valid from huaman.bitacora_evento where referencia=?",actor,action,input,key.toString());if(matches.isEmpty())return Optional.empty();if(matches.size()!=1||!Boolean.TRUE.equals(matches.getFirst().get("valid")))throw new com.ferreteriahuaman.security.AuthFailure(409,"La clave ya corresponde a otra solicitud");return Optional.of(((Number)matches.getFirst().get("id_entidad")).longValue());}
 public long opening(Opening i,String units){return jdbc.queryForObject("select huaman.apertura_stock(?,?,?,?,?::jsonb)",Long.class,i.productoId(),i.cantidad(),i.costoUnitarioBase(),i.clave(),units);}
 public Page<Movement> movements(long product,int page,int size,boolean costs){long total=jdbc.queryForObject("select count(*) from huaman.movimiento_inventario where id_producto=?",Long.class,product);return new Page<>(jdbc.query("select * from huaman.movimiento_inventario where id_producto=? order by id_movimiento desc limit ? offset ?",(r,n)->new Movement(r.getLong("id_movimiento"),r.getString("tipo_movimiento"),r.getString("sentido"),decimal(r,"cantidad"),decimal(r,"saldo_anterior"),decimal(r,"saldo"),costs?decimal(r,"costo_unitario_base"):null,r.getObject("feccre",LocalDateTime.class)),product,size,(long)page*size),total,page,size);}
 public Page<Existence> existences(long product,int page,int size){long total=jdbc.queryForObject("select count(*) from huaman.unidad_existencia where id_producto=?",Long.class,product);return new Page<>(jdbc.query("select * from huaman.unidad_existencia where id_producto=? order by id_unidad_existencia limit ? offset ?",(r,n)->new Existence(r.getLong("id_unidad_existencia"),r.getString("identificador"),r.getString("condicion_fisica"),decimal(r,"cantidad_inicial_base"),decimal(r,"cantidad_disponible_base"),r.getObject("id_presentacion",Long.class),r.getString("estado")),product,size,(long)page*size),total,page,size);}
}
